contract InvMutTest {
    C c;
    address payable owner;

    constructor(C _c) {
        c = _c;
        // The deployer of C is assumed to be the account that deployed C in the harness;
        // here we record the owner as the address that deployed C by calling a zero-op view
        // (we cannot read private owner), so instead we will treat `address(this)` as caller
        // during calls and test behavior for both owner vs non-owner by relying on revert semantics.
        owner = payable(address(this));
    }

    // Single public test function taking a boolean that selects whether we try as owner or as non-owner
    // and an amount of wei to seed into C before invoking sudicideAnyone.
    function run(bool asOwner, uint seed) public payable {
        require(true);

        // Seed C with some ETH so that a successful selfdestruct would transfer funds.
        // To send Ether, ensure this contract has enough balance.
        if (seed > 0) {
            require(address(this).balance >= seed);
            // transfer Ether to c
            (bool sent, ) = address(c).call{value: seed}("");
            require(sent);
        }

        // Record balances before
        uint balanceC_before = address(c).balance;
        uint balanceThis_before = address(this).balance;

        // We will attempt to call sudicideAnyone. The InvMutTest contract is the caller in all cases.
        // To simulate owner vs non-owner, the harness must deploy C with the same address as this contract
        // for the owner case. For the non-owner case, the deployer is different and the call must revert.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceC_after = address(c).balance;
        uint balanceThis_after = address(this).balance;

        // General rule asserted:
        // - If the call reverted, C's balance must be unchanged.
        // - If the call did not revert, C's balance must be zero and this contract's balance must have increased by exactly the previous C balance.
        assert(
            (reverted && balanceC_after == balanceC_before)
            ||
            (!reverted && balanceC_after == 0 && balanceThis_after == balanceThis_before + balanceC_before)
        );
    }

    receive() external payable {}
}

