contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tests owner-only selfdestruct behavior
    // params: callerIsOwner indicates whether this contract should attempt to act as owner
    // amount: ether to send with the call (though sudicideAnyone takes no value, we allow parameterization)
    function run(bool callerIsOwner, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // record balance of c before
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // If callerIsOwner == true, we want the call to be made by the owner of C.
        // The checker deploys a fresh C and its owner is the deployer (per prompt: "constructor of sGuardPlus sets __owner = msg.sender").
        // InvMutTest's constructor received C deployed elsewhere; we cannot change who is owner now.
        // So we detect expected behavior: if this contract is the owner of c, the call should not revert and balance of c should go to zero and transfer to msg.sender (this contract).
        // If this contract is not the owner, the call must revert and balances must remain unchanged.

        // Attempt the call and catch revert
        try c.sudicideAnyone{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // Determine whether this contract was actually the owner by observing effect: if call did not revert then contract was owner and selfdestruct should have forwarded c's funds to address(this), making c balance zero and increasing this balance by beforeC.
        // General rule asserted: (call reverted) XOR ((afterC == 0) && (afterThis == beforeThis + beforeC))
        // That is: either call reverted and balances unchanged, or call succeeded and all funds moved from c to this.
        assert( (reverted && afterC == beforeC && afterThis == beforeThis) ||
                (!reverted && afterC == 0 && afterThis == beforeThis + beforeC) );
    }

    // accept ether if selfdestruct forwards funds
    receive() external payable { }
}

