    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition
        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;
        bool reverted;
        // Call sudicideAnyone and catch revert (no value sent; function is non-payable)
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;
        // Either it reverted and balances unchanged, or it succeeded, C.balance == 0 and this contract's balance increased by exactly beforeC
        assert(
            (reverted && afterC == beforeC && afterMe == beforeMe)
            || (!reverted && afterC == 0 && afterMe == beforeMe + beforeC)
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool callIt) public payable {
        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;
        bool reverted;
        // perform the state-changing call as its own top-level statement
        if (callIt) {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If caller chooses not to call, treat as a no-op: reverted = true and balances unchanged
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;
        // Either the attempted call reverted (or was not invoked) leaving balances unchanged,
        // or it succeeded and C.balance == 0 and this contract received exactly the previous C balance.
        assert(
            (reverted && afterC == beforeC && afterMe == beforeMe)
            || (!reverted && afterC == 0 && afterMe == beforeMe + beforeC)
        );
    }
    receive() external payable {}
}

