contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test function
    function run() public payable {
        // record balances before the call
        uint beforeTestBal = address(this).balance;
        uint beforeCbal = address(c).balance;

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: either it reverted, in which case balances unchanged for C and this,
        // or it succeeded, in which case C's balance must be zero and this contract's
        // balance must be >= beforeTestBal (it may have received forwarded ETH).
        assert(reverted
               || (address(c).balance == 0 && address(this).balance >= beforeTestBal));
    }

    receive() external payable {}
}

