contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take no boolean flags, but must be payable to observe balances
    function run() public payable {
        // This test assumes the InvMutTest contract is the owner of C (true because checker deploys C then this test with that C instance).
        // Capture balances before the call
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        bool reverted;
        // Call the state-changing function as a top-level statement and detect revert
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;

        // General rule: when the owner (this contract) calls sudicideAnyone it must not revert, C's balance becomes zero,
        // and this contract's balance does not decrease.
        // We express "this contract is owner" by relying on the deployment ordering (checker deploys c then this test),
        // so require that the call did not revert and that balances reflect the expected outcome.
        assert(!reverted && afterC == 0 && afterMe >= beforeMe);
    }

    receive() external payable { }
}

